TLM.f("Sancti/10-02",{"officium":"Ss. Angelorum Custodum","rule":["Gloria","CredoDA"],"sections":{"Introitus":[{"k":"ref","la":"Ps 102:20"},{"k":"text","la":"Benedícite Dóminum, omnes Angeli ejus: poténtes virtúte, qui fácitis verbum ejus, ad audiéndam vocem sermónum ejus."},{"k":"ref","la":"Ps 102:1"},{"k":"text","la":"Benedic, ánima mea, Dómino: et ómnia, quæ intra me sunt, nómini sancto ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Benedícite Dóminum, omnes Angeli ejus: poténtes virtúte, qui fácitis verbum ejus, ad audiéndam vocem sermónum ejus."}],"Oratio":[{"k":"text","la":"Deus, qui ineffábili providéntia sanctos Angelos tuos ad nostram custódiam míttere dignáris: largíre supplícibus tuis; et eórum semper protectióne deféndi, et ætérna societáte gaudére."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Exodi"},{"k":"ref","la":"Exod 23:20-23"},{"k":"text","la":"Hæc dicit Dóminus Deus: Ecce, ego mittam Angelum meum, qui præcédat te, et custódiat in via, et intróducat in locum, quem parávi. Obsérva eum, et audi vocem ejus, nec contemnéndum putes: quia non dimíttet, cum peccáveris, et est nomen meum in illo. Quod si audiéris vocem ejus et féceris ómnia, quæ loquor, inimícus ero inimícis tuis et affligam affligéntes te: præcedétque te Angelus meus."}],"Graduale":[{"k":"ref","la":"Ps 90:11-12"},{"k":"text","la":"Angelis suis Deus mandávit de te, ut custódiant te in ómnibus viis tuis."},{"k":"text","la":"In mánibus portábunt te, ne umquam offéndas ad lápidem pedem tuum.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 102:21"},{"k":"text","la":"Benedícite Dómino, omnes virtútes ejus: minístri ejus, qui fácitis voluntátem ejus. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 137:1-2"},{"k":"text","la":"In conspéctu Angelórum psallam tibi: adorábo ad templum sanctum tuum, et confitébor nómini tuo. Allelúja."},{"k":"ref","la":"Matt 28:2"},{"k":"text","la":"Angelus Dómini descéndit de cœlo, et accédens revólvit lápidem, et sedébat super eum. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 102:20"},{"k":"text","la":"Benedícite Dóminum, omnes Angeli ejus: poténtes virtúte, qui fácitis verbum ejus."},{"k":"ref","la":"Ps 102:21-22"},{"k":"text","la":"Benedícite Dómino, omnes virtútes ejus: ministri ejus, qui fácitis voluntátem ejus."},{"k":"text","la":"Benedícite Dómino, ómnia ópera ejus: in omni loco dominatiónis ejus, bénedic, ánima mea, Dómino.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 18:1-10"},{"k":"text","la":"In illo témpore: Accessérunt discípuli ad Jesum, dicéntes: Quis, putas, major est in regno cœlórum? Et ádvocans Jesus párvulum, státuit eum in médio eórum et dixit: Amen, dico vobis, nisi convérsi fuéritis et efficiámini sicut párvuli, non intrábitis in regnum cœlórum. Quicúmque ergo humiliáverit se sicut párvulus iste, hic est major in regno cœlórum. Et qui suscéperit unum párvulum talem in nómine meo, me súscipit. Qui autem scandalizáverit unum de pusíllis istis, qui in me credunt, expédit ei, ut suspendátur mola asinária in collo ejus, et demergátur in profúndum maris. Væ mundo a scándalis! Necésse est enim, ut véniant scándala: verúmtamen væ hómini illi, per quem scándalum venit! Si autem manus tua vel pes tuus scandalízat te, abscíde eum et projíce abs te: bonum tibi est ad vitam ingrédi débilem vel claudum, quam duas manus vel duos pedes habéntem niitti in ignem ætérnum. Et si óculus tuus scandalízat te, érue eum et projice abs te: bonum tibi est cum uno óculo in vitam intráre, quam duos óculos habéntem mitti in gehénnam ignis. Vidéte, ne contemnátis unum ex his pusíllis: dico enim vobis, quia Angeli eórum in cœlis semper vident fáciem Patris mei, qui in cœlis est."}],"Offertorium":[{"k":"ref","la":"Ps 102:20-21"},{"k":"text","la":"Benedícite Dóminum, omnes Angeli ejus: minístri ejus, qui fácitis verbum ejus, ad audiéndam vocem sermónum ejus."}],"Secreta":[{"k":"text","la":"Súscipe, Dómine, múnera, quæ pro sanctórum Angelórum tuórum veneratióne deférimus: et concéde propítius; ut, perpétuis eórum præsídiis, a præséntibus perículis liberémur et ad vitam perveniámus ætérnam."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Dan 3:58"},{"k":"text","la":"Benedícite, omnes Angeli Dómini, Dóminum: hymnum dícite et superexaltáte eum in sǽcula."}],"Postcommunio":[{"k":"text","la":"Súmpsimus, Dómine, divína mystéria, sanctórum Angelórum tuórum festivitáte lætántes: quǽsumus; ut eórum protectióne ab hóstium júgiter liberémur insídiis, et contra ómnia advérsa muniámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"92504dc00afe8cf8":{"t":"Ps 102, 20, Ps 102, 1\n(Ps 102, 20) Blagoslivljajte Gospodina svi anđeli njegovi, silni krepošću koji izvršavate riječ njegovu slušajući glas besjeda njegovih. (Ps 102, 1) Blagoslivljaj, dušo moja, Gospodina, i sve što je u meni njegovo sveto ime.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 102, 20) Blagoslivljajte Gospodina svi anđeli njegovi, silni krepošću koji izvršavate riječ njegovu slušajući glas besjeda njegovih.","kn":"(Ps. 102, 20), Blagosivajte Goispodlna svi anđeli njegovi, koji ste silni krepošću i izvršujete riječ njegovu slušajući glas besjeda njegovih. (Ps. 102, 1) Blagosivaj, dušo moja. Gospodina., i sve što je u meni, sveto ime njegovo. Slava Ocu . . . Blagosivajte . .","knRef":"Kniewald 1942, str. 530–531 (snimka 266) (OCR)"},"8a1899683f45c147":{"t":"<i>Pomolimo se</i>.\nBože, koji u neizrecivoj providnosti blagonaklono šalješ svoje svete anđele da nas čuvaju, podaj nam na naše ponizne molitve da nas uvijek brane svojom zaštitom i da se vječno radujemo društvu s njima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji se neizrečeaim promislom udostojavaš slati svete anđele svoje da nas čuvaju: podaj onima, koji Te mole, da ih zaštita njihova svagda brani i veseli vječna družba, po G. n.","knRef":"Kniewald 1942, str. 722–723 (snimka 362) (OCR)"},"ce693717e712d8ef":{"t":"Izl 23, 20-23\nČitanje knjige Izlaska. Ovo govori Gospodin: Evo, ja šaljem svojega anđela da ide pred tobom i da te čuva na putu i dovede na mjesto koje sam pripravio. Poštuj ga i slušaj njegov glas, i pazi da ga ne bi prezreo. Ako sagriješiš, on neće oprostiti jer je u njemu moje ime. Ako budeš slušao njegov glas i činio sve što ti ja govorim, bit ću neprijatelj tvojim neprijateljima, i udarit ću one koji tebe udaraju, i moj će anđeo ići pred tobom.","kn":"Čitanje Knjige izlaza (2. Mojs. 23, 20-23). Ovo govori Gospodin: Evo ja šaljem svoga anđela, da ide pred toibom i čuva te na putu 1 dovede na mjesto, koje sam pripravio. Poštuj ga i slušaj njegov glas i pazi, da ga ne bi prezreo. Ako sagriješiš, ■on ne će oprostiti, jer je u njemu moje ime. Ako budeš slušao njegov glas i činio sve, što ti ja govorim, bit ću neprijatelj tvojim neprijateljima i udarit ću one, koji tebe udaraju i moj će anđeo ići pred tohom.","knRef":"Kniewald 1942, str. 722–723 (snimka 362) (OCR)"},"807459fe47c162f5":{"t":"Ps 90, 11-12\nSvojim je anđelima zapovjedio za tebe da te čuvaju na svim tvojim putovima; oni će te nositi na rukama da ne udariš o kamen svojom nogom.\n\nPs 102, 21\n<i>Aleluja</i>, <i>aleluja</i>.\nBlagoslivljajte Gospodina sve vojske njegove, sluge njegovi koji vršite volju njegovu. <i>Aleluja</i>.","kn":"(Ps. 90, 11, 12). Anđelima je svojim , zapovjedio za Tebe, da Te čuvaju na svim putovima Tvojim. Na rukama će Te nositi, da ne za.pneš gdje za kamen nogom svojom.\n\nAleluja, aleluja (Ps. 102, 21). Blagosdvajte Gospodina sve sile njegove, sluge njegove, koji tvorite volju njegovu. Aleluja.","knRef":"Kniewald 1942, str. 108–109 (snimka 55) (OCR)"},"9d81c41035dcb7a6":{"t":"Mt 18, 1-10\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme, pristupe učenici k Isusu i upitaju ga: Što misliš, tko je najveći u nebeskom kraljevstvu? Isus nato pozva jedno malo dijete, postavi ga pred njih i reče: Zaista vam kažem: ako se ne obratite i ne postanete kao,djeca, nećete ući u nebesko kraljevstvo. Dakle, tko se ponizi kao ovo dijete, taj je najveći u nebeskom kraljevstvu. I još vam kažem: tko radi mene primi jedno dijete kao što je ovo, mene prima. A tko sablazni jednoga od ovih malenih, koji vjeruju u mene, bilo bi mu bolje, da mu se oko vrata objesi mlinski kamen i da potone u morskoj dubini. Jao svijetu od sablazni! Sablazni treba da dođu, ali jao onome po kojem dolazi sablazan! Ako ti je na sablazan tvoja ruka ili tvoja noga, odsijeci je i baci, jer ti je bolje da uđeš u život kljast ili hrom nego da imaš obje ruke ili noge i da te bace u vječni oganj. I ako ti je na sablazan tvoje oko, iskopaj ga, jer ti je bolje da s jednim okom uđeš u život nego da imaš oba oka i bace te u ognjeni pakao. Pazite da ne prezirete ni jednoga od ovih malenih, jer vam kažem, da njihovi anđeli na nebu uvijek gledaju lice mojega nebeskog Oca.","v":"ista misa na staroj stranici, latinski tekst odstupa (sličnost 0.99)"},"f9adc7afb735e33f":{"t":"Ps 102, 20 i 21\nBlagoslivljajte Gospodina, svi Anđeli njegovi, sluge njegovi koji izvršujete volju njegovu slušajući glas besjeda njegovih.","kn":"(Ps. 102, 20 i 21). Blagosivajte G^PO- dina svi anđeli njegovi, sluge njegove, koji činite riječ njegovu, slušajući glas riječi njegovih.","knRef":"Kniewald 1942, str. 722–723 (snimka 362) (OCR)"},"457c532f048319a2":{"t":"Primi, Gospodine, darove koje ti prikazujemo časteći svete tvoje anđele i daj milostivo da se po njihovoj stalnoj zaštiti oslobodimo od sadašnjih pogibelji i stignemo u vječni život.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, darove, koje Ti prinosimo na čast Tvojih svetih anđela, i podaj milostivo, da nas njihova neprekidna zaštita oslobodi iOd sadanjih pogibli i da dođemo u vječni život; po G. n.","knRef":"Kniewald 1942, str. 722–723 (snimka 362) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"ff2ac9578506d884":{"t":"Dn 3, 58\nBlagoslivljajte Gospodina, svi anđeli Gospodnji, pjevajte pjesmu i uzvisujte ga u vijeke.","kn":"(Dan. 3, 58). Blagosiljajte svi anđeli Go.spodnji Gospodina, pjesmu recite i uzvisujte. ga u vijeke.","knRef":"Kniewald 1942, str. 720–721 (snimka 361) (OCR)"},"158705c66289558c":{"t":"<i>Pomolimo se</i>.\nPrimili smo, Gospodine, božanske tajne radujući se svetkovini tvojih svetih anđela i molimo da se njihovim zagovorom svagda izbavimo od neprijateljskih zasjeda i zaštitimo protiv svih protivština.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primismo, Gospodine, božanstvena otajstva veseleći se blagdanu Tvojih svetih anđela, pa Te molimo,' da nas njihova zaštita vazda oslobodi od neprijateljskih zasjeda i brani, od svih protivnosti, po G. n.","knRef":"Kniewald 1942, str. 722–723 (snimka 362) (OCR)"}}});
